import React from "react";
import { Link, useNavigate } from "react-router-dom";
import { Leaf, ShoppingBag, User, LogOut } from "lucide-react";
import { useCart } from "../context/CartContext";
import { useAuth } from "../context/AuthContext";

export default function Header({ onCartClick }) {
  const { count } = useCart();
  const { user, logout } = useAuth();
  const navigate = useNavigate();

  return (
    <header
      style={{
        position: "sticky",
        top: 0,
        zIndex: 40,
        background: "var(--bg)",
        borderBottom: "1px solid var(--border)",
        backdropFilter: "blur(6px)",
      }}
    >
      <div className="container" style={{ padding: "16px 24px", display: "flex", alignItems: "center", justifyContent: "space-between" }}>
        <Link to="/" className="focus-ring" style={{ display: "flex", alignItems: "center", gap: 8 }}>
          <span
            style={{
              width: 34,
              height: 34,
              borderRadius: "50%",
              background: "var(--forest)",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
            }}
          >
            <Leaf size={18} color="#F5F6ED" strokeWidth={2.5} />
          </span>
          <span className="disp" style={{ fontSize: 21, fontWeight: 700, color: "var(--forest-dark)", letterSpacing: "-0.02em" }}>
            Healthy Food
          </span>
        </Link>

        <nav style={{ display: "flex", gap: 4, alignItems: "center" }}>
          <NavLink to="/menu">Menu</NavLink>
          <NavLink to="/orders">Track Order</NavLink>

          {user ? (
            <button
              onClick={() => {
                logout();
                navigate("/");
              }}
              className="focus-ring"
              title="Log out"
              style={{
                marginLeft: 8,
                display: "flex",
                alignItems: "center",
                gap: 6,
                padding: "8px 14px",
                borderRadius: 999,
                border: "1px solid var(--border)",
                background: "#FFFFFF",
                fontSize: 13.5,
                fontWeight: 700,
                color: "#3E3E36",
              }}
            >
              <User size={15} /> {user.name.split(" ")[0]} <LogOut size={13} />
            </button>
          ) : (
            <NavLink to="/login">Log in</NavLink>
          )}

          <button
            onClick={onCartClick}
            className="focus-ring"
            style={{
              position: "relative",
              marginLeft: 8,
              width: 40,
              height: 40,
              borderRadius: "50%",
              border: "1px solid var(--border)",
              background: "#FFFFFF",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
            }}
          >
            <ShoppingBag size={18} color="var(--forest)" />
            {count > 0 && (
              <span
                style={{
                  position: "absolute",
                  top: -4,
                  right: -4,
                  background: "var(--tomato)",
                  color: "#fff",
                  fontSize: 11,
                  fontWeight: 800,
                  borderRadius: 999,
                  minWidth: 18,
                  height: 18,
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  padding: "0 4px",
                }}
              >
                {count}
              </span>
            )}
          </button>
        </nav>
      </div>
    </header>
  );
}

function NavLink({ to, children }) {
  return (
    <Link
      to={to}
      className="focus-ring"
      style={{
        padding: "8px 14px",
        borderRadius: 999,
        fontSize: 14,
        fontWeight: 600,
        color: "#3E3E36",
      }}
    >
      {children}
    </Link>
  );
}
